  "headline": "Cisplatin shortage ongoing since 2023-02-10 with key manufacturing sites showing repeated VAI inspections",
  "headline_cites": ["D5", "E10", "E11", "E14", "E15", "E16"],
  "sentences": [
    {
      "text": "FDA's shortage list shows cisplatin has been in shortage since 2023-02-10 and remained listed as of 2026-10-21, a duration of 44 months.",
      "cites": ["D5"]
    },
    {
      "text": "The Thymoorgan Pharmazie GmbH facility in Germany (FEI 3002320821), which manufactures cisplatin for Hikma Pharmaceuticals USA Inc., received VAI classifications in its last two FDA inspections ending 2022-10-06 and 2023-04-25.",
      "cites": ["E10", "E11", "E12"]
    },
    {
      "text": "The Gland Pharma Limited facility in India (FEI 3009056604), a registered plant for cisplatin, received VAI classifications in three consecutive FDA inspections ending 2013-08-05, 2015-06-30, and 2019-11-01.",
      "cites": ["E14", "E15", "E16", "E17"]
    },
    {
      "text": "Intas Pharmaceuticals Limited, noted as a plant for cisplatin, had its last FDA inspection end on 2022-12-02 with an OAI classification.",
      "cites": []
    },
    {
      "text": "Current hospital inventory at Corvale East shows 18 days on hand and Corvale General shows 31 days on hand, indicating limited buffer against supply disruptions.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "Accord Healthcare Inc. is identified as the best purchasing option per current rules and is not on FDA's shortage list as of 2026-10-21.",
      "cites": []
    }
  ]
}
